Continued pretraining.ejemplo:
# Empaquetado de documentos para Continued Pretraining (CLM)
def group_texts(examples, block_size=4096):
    concatenated = sum(examples["input_ids"], [])
    total_len = (len(concatenated) // block_size) * block_size
    return {"input_ids": [concatenated[i:i+block_size] for i in range(0, total_len, block_size)]}

