Reward model.ejemplo:
class RewardModel(nn.Module):
    def __init__(self, backbone, hidden_size):
        super().__init__()
        self.backbone = backbone
        self.score_head = nn.Linear(hidden_size, 1, bias=False)
    def forward(self, input_ids, attention_mask):
        last_hidden = self.backbone(input_ids, attention_mask).last_hidden_state[:, -1, :]
        return self.score_head(last_hidden).squeeze(-1)

